/**
 * @name Path traversal vulnerability
 * @description User-controlled input flowing to file operations without proper validation
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability: user input flows to file operation $@.", source.getNode(), "user input"

/**
 * @name File path injection in charset detection
 * @description User-controlled file paths flowing to file open operations
 * @kind path-problem
 * @problem.severity high
 * @id py/charset-file-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FilePathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    // os.path operations that might be used before file open
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "realpath"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module FilePathFlow = TaintTracking::Global<FilePathConfig>;
import FilePathFlow::PathGraph

from FilePathFlow::PathNode source, FilePathFlow::PathNode sink
where FilePathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File path injection from $@.", source.getNode(), "user input"
